@Route(value = "", layout = MainLayout.class)
@PageTitle("Items")
class ItemsView extends VerticalLayout {

    private final TextField itemField;
    private final UnorderedList itemList;
    private final Span itemCount;

    ItemsView() {
        itemField = new TextField("Item");

        var addBtn = new Button("Add", event -> addItem());
        addBtn.addThemeVariants(ButtonVariant.PRIMARY);
        var clearBtn = new Button("Clear", event -> clearItems());

        var form = new HorizontalLayout(itemField, addBtn, clearBtn);
        form.setDefaultVerticalComponentAlignment(FlexComponent.Alignment.END);

        itemList = new UnorderedList();
        itemCount = new Span();
        updateCount();

        add(new ViewTitle("Items"), form, itemList, itemCount);
    }

    private void addItem() {
        var value = itemField.getValue();
        if (value.isBlank()) {
            itemField.setInvalid(true);
            itemField.setErrorMessage("Item is required");
            return;
        }
        itemList.add(new ListItem(value));
        itemField.clear();
        itemField.setInvalid(false);
        updateCount();
    }

    private void clearItems() {
        itemList.removeAll();
        updateCount();
    }

    private void updateCount() {
        itemCount.setText("Items: " + itemList.getChildren().count());
    }
}
